    var c=document.createElement('div');c.className='lcard';c.style.setProperty('--c',best.c);c.innerHTML=cardHTML(best);res.innerHTML='';res.appendChild(c);
    if(hasG&&!REDUCE){gsap.fromTo(c,{clipPath:'inset(100% 0 0 0)'},{clipPath:'inset(0% 0 0 0)',duration:1.2,ease:'expo.inOut'});gsap.from($('.f',c),{yPercent:12,duration:1.4})}
    $('#qzAgain').addEventListener('click',function(){step=0;score={};res.innerHTML='<div class="lcard secret" style="--c:#FF5257"><div class="nm" style="font-size:25cqw">???</div><div class="sh"></div><div class="f fig fig-synapse" style="filter:brightness(0)"></div><div class="no"><i></i><span>NO.</span><b>??</b></div><div class="ar"><span>Your signal</span></div></div>';show()});
