  /* hover tilt on the shelf (inner layer only, hit area stays still) */
  if(FINE&&hasG)$$('.pbox').forEach(function(b){var inr=$('.pbox-in',b),rx=gsap.quickTo(inr,'rotationY',{duration:.6,ease:'power3'}),ry=gsap.quickTo(inr,'rotationX',{duration:.6,ease:'power3'});
    b.addEventListener('pointermove',function(e){if(state!=='pick')return;var r=b.getBoundingClientRect();rx(((e.clientX-r.left)/r.width-.5)*18);ry(-((e.clientY-r.top)/r.height-.5)*12)});
    b.addEventListener('pointerleave',function(){rx(0);ry(0)})});
  shelf.addEventListener('click',function(e){var b=e.target.closest('.pbox');if(!b||state!=='pick')return;choose(b)});
  function choose(b){state='armed';setTimeout(softRefresh,1300);var r0=$('.pbox-in',b).getBoundingClientRect();rev.hidden=false;hold.hidden=false;again.hidden=true;file.hidden=true;msg.textContent='Box '+(+b.getAttribute('data-i')+1)+' selected';res.textContent='Press and hold to open.';
    gsap.set($$('.pks',box),{clearProps:'all'});fit();gsap.set(box,{opacity:1});gsap.set(fig,{clipPath:'inset(100% 0 0 0)'});gsap.set(card,{rotationY:180});gsap.set('#pkCard',{opacity:0,x:40});$('#pkCard').hidden=true;gsap.set(scan,{opacity:0});
    if(!hasG||REDUCE){shelf.classList.add('gone');setTimeout(function(){hold.focus({preventScroll:true})},30);return}
    var others=$$('.pbox').filter(function(x){return x!==b});
    gsap.to(others,{y:60,opacity:0,duration:.5,ease:'expo.in',stagger:.03});
    gsap.to(b,{opacity:0,duration:.2,delay:.3,onComplete:function(){shelf.classList.add('gone')}});
    var r1=box.getBoundingClientRect();gsap.fromTo(box,{x:r0.left-r1.left,y:r0.top-r1.top,scale:r0.width/r1.width},{x:0,y:0,scale:1,duration:1,ease:'expo.inOut',delay:.15,onComplete:function(){hold.focus({preventScroll:true})}});
    gsap.from('.pk-side>*:not(#pkCard)',{y:20,opacity:0,stagger:.06,duration:.8,delay:.5});
    if(innerWidth<861)setTimeout(function(){glide($('#pkStage'))},350)}
