    hold.hidden=true;$('#pkCard').hidden=false;msg.textContent=r.secret?'Secret · 1 in 144':'No. '+r.no+' · about 1 in 8';res.innerHTML=r.secret?'SYNAPSE. <em>The Glitch.</em>':'You pulled '+r.n+'. <em>'+r.arch+'.</em>';
